  g_cuda_funcs.cublasSetStream = reinterpret_cast<decltype(&::cublasSetStream)>(
      dlsym(g_cublas_handle, "cublasSetStream_v2"));
  g_cuda_funcs.cublasGetStream = reinterpret_cast<decltype(&::cublasGetStream)>(
