      !g_cuda_funcs.cublasIdamax) {
    fprintf(stderr, "Failed to resolve cuBLAS symbols: %s\n", dlerror());
    dlclose(g_cudss_handle);
    dlclose(g_cusparse_handle);
    dlclose(g_cublas_handle);
    return 0;
  }

  g_libs_loaded = 1;
  return 1;
