}

void sync_vector_to_device(QOCOVectorf* v)
{
  if (v && v->data && v->d_data) {
    CUDA_CHECK(cudaMemcpy(v->d_data, v->data, v->len * sizeof(QOCOFloat),
                          cudaMemcpyHostToDevice));
